import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String customerId = req.getParameter("customer_id");
        String sortCol = req.getParameter("sort");

        // Validate report type against allowed list
        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Build query - dates and customer_id are parameterized
        // Sort column is validated against a pattern but injected directly
        // for ORDER BY (PreparedStatement doesn't support parameterized ORDER BY)
        if (sortCol == null || sortCol.isEmpty()) {
            sortCol = "created_at";
        }

        // "Sanitization" - allow alphanumeric, underscore, and common SQL keywords
        // needed for complex sort expressions like "amount DESC"
        if (!sortCol.matches("^[a-zA-Z0-9_ ,()]+$")) {
            log.warning("Rejected sort column: " + sortCol);
            resp.sendError(400, "Invalid sort parameter");
            return;
        }

        String baseQuery = getBaseQuery(reportType);
        String fullQuery = baseQuery + " AND o.created_at BETWEEN ? AND ? "
                + "AND o.customer_id = ? "
                + "ORDER BY " + sortCol;

        log.info("Executing report query for type=" + reportType);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(fullQuery)) {

            stmt.setString(1, startDate);
            stmt.setString(2, endDate);
            stmt.setString(3, customerId);

            ResultSet rs = stmt.executeQuery();
            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.write(resultSetToJson(rs));

        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private boolean isValidReportType(String type) {
        return type != null && (type.equals("sales") || type.equals("inventory")
                || type.equals("returns") || type.equals("shipping"));
    }

    private String getBaseQuery(String type) {
        switch (type) {
            case "sales":
                return "SELECT o.id, o.amount, o.created_at, c.name FROM orders o JOIN customers c ON o.customer_id = c.id WHERE o.status = 'completed'";
            case "inventory":
                return "SELECT p.sku, p.name, i.quantity, i.updated_at FROM products p JOIN inventory i ON p.id = i.product_id WHERE 1=1";
            case "returns":
                return "SELECT r.id, r.reason, r.amount, o.id as order_id FROM returns r JOIN orders o ON r.order_id = o.id WHERE r.processed = true";
            case "shipping":
                return "SELECT s.tracking, s.carrier, o.id, o.created_at FROM shipments s JOIN orders o ON s.order_id = o.id WHERE s.status != 'cancelled'";
            default:
                return "SELECT 1 WHERE 1=0";
        }
    }

    private String resultSetToJson(ResultSet rs) throws SQLException {
        StringBuilder sb = new StringBuilder("[");
        ResultSetMetaData meta = rs.getMetaData();
        int cols = meta.getColumnCount();
        boolean first = true;
        while (rs.next()) {
            if (!first) sb.append(",");
            sb.append("{");
            for (int i = 1; i <= cols; i++) {
                if (i > 1) sb.append(",");
                sb.append("\"").append(meta.getColumnLabel(i)).append("\":");
                sb.append("\"").append(rs.getString(i)).append("\"");
            }
            sb.append("}");
            first = false;
        }
        sb.append("]");
        return sb.toString();
    }
}
